import { encodeAscii, UnicodeEncodeError } from './lib/ascii.mjs';
import { CliExit, parseCommandLine } from './lib/argparse_like.mjs';
import { decode, encode } from './lib/bencoder.mjs';
import { repr } from './lib/python_repr.mjs';

function basename(pathname) {
  if (!pathname) {
    return 'test12.mjs';
  }

  const normalized = pathname.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] || pathname;
}

function writeCliExit(error) {
  if (error.stdoutText) {
    process.stdout.write(error.stdoutText);
  }

  if (error.stderrText) {
    process.stderr.write(error.stderrText);
  }

  process.exit(error.code);
}

function encodeArgument(text, pythonLineNumber) {
  try {
    return encodeAscii(text);
  } catch (error) {
    if (error instanceof UnicodeEncodeError) {
      error.pythonLineNumber = pythonLineNumber;
    }

    throw error;
  }
}

function writeUnicodeEncodeError(error, scriptName) {
  const lineNumber = error.pythonLineNumber ?? 1;
  process.stderr.write('Traceback (most recent call last):\n');
  process.stderr.write(
    `  File "${scriptName}", line ${lineNumber}, in <module>\n`,
  );
  process.stderr.write(`${error.name}: ${error.message}\n`);
  process.exit(1);
}

function main() {
  const scriptName = basename(process.argv[1]);
  const args = parseCommandLine(process.argv.slice(2), scriptName);

  const firstKey = encodeAscii('first');
  const secondKey = encodeAscii('second');
  const numberKey = encodeAscii('number');
  const firstValue = encodeArgument(args.a, 10);
  const secondValue = encodeArgument(args.b, 11);

  const dict1 = new Map([[firstKey, firstValue]]);
  const dict2 = new Map([
    [secondKey, secondValue],
    [numberKey, args.c],
  ]);
  const combined = [dict1, dict2];
  const encoded = encode(combined);
  const decoded = decode(encoded);
  const encodedDict1 = encode(dict1);
  const encodedDict2 = encode(dict2);

  console.log(repr(encoded));
  console.log(repr(decoded));
  console.log(repr(encodedDict1));
  console.log(repr(encodedDict2));
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    writeCliExit(error);
  }

  if (error instanceof UnicodeEncodeError) {
    writeUnicodeEncodeError(error, basename(process.argv[1]));
  }

  throw error;
}
